-- Check how many containers total and if all have sensor data
SELECT COUNT(*) as total_containers FROM container;
SELECT COUNT(DISTINCT containlink) as containers_with_sensor_data FROM sensordata;

-- Check distinct values for sensor status fields
SELECT DISTINCT shockflag FROM sensordata ORDER BY shockflag;
SELECT DISTINCT tiltflag FROM sensordata ORDER BY tiltflag;
SELECT DISTINCT impactflag FROM sensordata ORDER BY impactflag;

-- Maybe TSS is stored as a separate field or needs to be calculated differently
-- Let me check what values tempstabidx has
SELECT MIN(tempstabidx), MAX(tempstabidx), AVG(tempstabidx) FROM sensordata;

-- Check if coolremainpct can be NULL
SELECT COUNT(*) FROM container WHERE coolremainpct IS NULL;
SELECT COUNT(*) FROM container WHERE containregistry NOT IN (SELECT containlink FROM sensordata);
